class Instrument:                 # base, written years ago
    def describe(self):
        return self.symbol

class Tick(Instrument):
    __slots__ = ("symbol", "price", "ts")
    def __init__(self, symbol, price, ts):
        self.symbol, self.price, self.ts = symbol, price, ts

class DebugTick(Tick):            # used by the replay tool — and, it turns out, in prod
    def __init__(self, *a):
        super().__init__(*a)
        self.note = "replay"      # works without AttributeError... suspicious

