# Иерархия: Instrument (без слотов) → Tick (со слотами) → DebugTick (без слотов, добавляет note)
class Instrument:                 # база, написана годы назад
    def describe(self):
        return self.symbol

class Tick(Instrument):
    __slots__ = ("symbol", "price", "ts")
    def __init__(self, symbol, price, ts):
        self.symbol, self.price, self.ts = symbol, price, ts

class DebugTick(Tick):            # используется реплей-тулом — и, как выяснилось, в проде
    def __init__(self, *a):
        super().__init__(*a)
        self.note = "replay"      # работает без AttributeError... подозрительно

