from dataclasses import dataclass


@dataclass(unsafe_hash=True)
class Session:
    user_id: int
    region: str
    last_seen: float = 0.0


active: set[Session] = set()


def touch(s: Session, now: float) -> None:
    active.add(s)
    s.last_seen = now  # refresh activity timestamp


def evict_idle(cutoff: float) -> None:
    for s in list(active):
        if s.last_seen < cutoff:
            active.discard(s)


@dataclass(order=True)
class Event:
    id: int
    ts: float


def replay_order(events: list[Event]) -> list[Event]:
    return sorted(events)

